<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
saas_require_login();
$tourId=saas_require_tour();
saas_require_permission('tour.update');
$db=saas_db();$error='';$ok='';
$q=$db->prepare('SELECT * FROM tours WHERE id=? AND organization_id=?');$q->execute([$tourId,saas_current_organization_id()]);$tour=$q->fetch();
$q=$db->prepare('SELECT * FROM tour_public_pages WHERE tour_id=?');$q->execute([$tourId]);$page=$q->fetch();
if(!$page){$q=$db->prepare("INSERT INTO tour_public_pages(tour_id,status,theme_key,title) VALUES(?,?,?,?)");$q->execute([$tourId,'DRAFT','classic',$tour['name']]);$pageId=(int)$db->lastInsertId();$q=$db->prepare('SELECT * FROM tour_public_pages WHERE id=?');$q->execute([$pageId]);$page=$q->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){
 saas_check_csrf();
 try{
  $status=(string)($_POST['status']??'DRAFT');$theme=(string)($_POST['theme_key']??'classic');$title=trim((string)($_POST['title']??''));$subtitle=trim((string)($_POST['subtitle']??''));$cover=trim((string)($_POST['cover_image']??''));$logo=trim((string)($_POST['logo_image']??''));$primary=trim((string)($_POST['primary_color']??''));$secondary=trim((string)($_POST['secondary_color']??''));$seoTitle=trim((string)($_POST['seo_title']??''));$seoDesc=trim((string)($_POST['seo_description']??''));$allowedStatus=['DRAFT','PUBLISHED','CLOSED'];if(!in_array($status,$allowedStatus,true))throw new RuntimeException('Invalid page status.');
  $q=$db->prepare('UPDATE tour_public_pages SET status=?,theme_key=?,title=?,subtitle=?,cover_image=?,logo_image=?,primary_color=?,secondary_color=?,seo_title=?,seo_description=?,published_at=IF(?="PUBLISHED",COALESCE(published_at,NOW()),NULL) WHERE tour_id=?');$q->execute([$status,$theme,$title?:null,$subtitle?:null,$cover?:null,$logo?:null,$primary?:null,$secondary?:null,$seoTitle?:null,$seoDesc?:null,$status,$tourId]);
  saas_audit('public_page.updated','tour_public_page',(int)$page['id'],json_encode(['status'=>$status,'theme'=>$theme],JSON_UNESCAPED_UNICODE));$ok='Public page settings saved.';$q=$db->prepare('SELECT * FROM tour_public_pages WHERE tour_id=?');$q->execute([$tourId]);$page=$q->fetch();
 }catch(Throwable $e){$error=$e->getMessage();}
}
$slug=saas_h((string)$tour['slug']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Public Tour Page</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f4f7fb;margin:0;color:#172033}.wrap{max-width:1050px;margin:25px auto;padding:0 16px}.box{background:#fff;border-radius:16px;padding:22px;margin-bottom:18px;box-shadow:0 6px 22px #0000000b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{display:block;font-size:13px;font-weight:700;margin:11px 0 5px}input,select,textarea,button{width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}textarea{min-height:85px;resize:vertical}button{margin-top:15px;background:#155eef;color:#fff;border-color:#155eef;font-weight:700}.msg{padding:11px;border-radius:9px;margin-bottom:15px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}.preview{border-radius:14px;overflow:hidden;background:#172033;color:#fff;min-height:230px;padding:28px;display:flex;flex-direction:column;justify-content:flex-end}.badge{display:inline-block;background:#ffffff22;padding:6px 10px;border-radius:999px;font-size:12px;width:max-content}.muted{color:#667085;font-size:13px}@media(max-width:750px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="saas_dashboard.php">← Dashboard</a></p><h1>Public Tour Page</h1><?php if($ok):?><div class="msg ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=saas_h($error)?></div><?php endif;?><section class="box"><div class="preview"><span class="badge"><?=saas_h($page['status'])?></span><h2><?=saas_h($page['title']?:$tour['name'])?></h2><div><?=saas_h($page['subtitle']?:'Tour information, registration and updates will appear here.')?></div></div><p class="muted">The public URL will use the tour slug: <strong>/tour/<?=$slug?></strong>. Routing can be connected when the public registration module is enabled.</p></section><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><div class="grid"><section class="box"><h2>Page settings</h2><label>Status</label><select name="status"><option <?=($page['status']==='DRAFT'?'selected':'')?>>DRAFT</option><option <?=($page['status']==='PUBLISHED'?'selected':'')?>>PUBLISHED</option><option <?=($page['status']==='CLOSED'?'selected':'')?>>CLOSED</option></select><label>Theme</label><select name="theme_key"><option value="classic" <?=($page['theme_key']==='classic'?'selected':'')?>>Classic</option><option value="travel" <?=($page['theme_key']==='travel'?'selected':'')?>>Travel</option><option value="event" <?=($page['theme_key']==='event'?'selected':'')?>>Event</option></select><label>Title</label><input name="title" value="<?=saas_h($page['title']??'')?>"><label>Subtitle</label><textarea name="subtitle"><?=saas_h($page['subtitle']??'')?></textarea><label>Cover image path / URL</label><input name="cover_image" value="<?=saas_h($page['cover_image']??'')?>"><label>Logo image path / URL</label><input name="logo_image" value="<?=saas_h($page['logo_image']??'')?>"></section><section class="box"><h2>Branding & SEO</h2><label>Primary color</label><input name="primary_color" placeholder="#155eef" value="<?=saas_h($page['primary_color']??'')?>"><label>Secondary color</label><input name="secondary_color" placeholder="#0f172a" value="<?=saas_h($page['secondary_color']??'')?>"><label>SEO title</label><input name="seo_title" value="<?=saas_h($page['seo_title']??'')?>"><label>SEO description</label><textarea name="seo_description"><?=saas_h($page['seo_description']??'')?></textarea><p class="muted">Next stage will add editable sections such as overview, itinerary, gallery, pricing, bus/seat plan, rooms, contacts and registration.</p><button>Save public page</button></section></div></form></main></body></html>
